import numpy as np


class Layer_Dense:
    def __init__(self, n_inputs, n_neurons):
        self.weights = 0.01 * np.random.randn(n_inputs, n_neurons)
        self.biases = np.zeros((1, n_neurons))

    def forward(self, inputs):
        self.output = np.dot(inputs, self.weights) + self.biases


class Activation_ReLU:
    def forward(self, inputs):
        self.output = np.maximum(0, inputs)


class Activation_Softmax:
    def forward(self, inputs):
        shifted = inputs - np.max(inputs, axis=1, keepdims=True)
        exp_values = np.exp(shifted)
        self.output = exp_values / np.sum(exp_values, axis=1, keepdims=True)


def build_network(sizes):
    """Return the list of objects for layer sizes such as [2, 3, 3]: only one hidden layer so far."""
    n_inputs, n_hidden, n_classes = sizes
    return [Layer_Dense(n_inputs, n_hidden), Activation_ReLU(),
            Layer_Dense(n_hidden, n_classes), Activation_Softmax()]


def forward_network(network, X):
    """Run X through the objects and return the probabilities: only four objects so far."""
    dense1, activation1, dense2, activation2 = network
    dense1.forward(X)
    activation1.forward(dense1.output)
    dense2.forward(activation1.output)
    activation2.forward(dense2.output)
    return activation2.output

questions.solution:
import numpy as np


class Layer_Dense:
    def __init__(self, n_inputs, n_neurons):
        self.weights = 0.01 * np.random.randn(n_inputs, n_neurons)
        self.biases = np.zeros((1, n_neurons))

    def forward(self, inputs):
        self.output = np.dot(inputs, self.weights) + self.biases


class Activation_ReLU:
    def forward(self, inputs):
        self.output = np.maximum(0, inputs)


class Activation_Softmax:
    def forward(self, inputs):
        shifted = inputs - np.max(inputs, axis=1, keepdims=True)
        exp_values = np.exp(shifted)
        self.output = exp_values / np.sum(exp_values, axis=1, keepdims=True)


def build_network(sizes):
    """Return the list of objects for layer sizes such as [2, 64, 64, 3], any number of hidden layers."""
    network = []
    for i in range(len(sizes) - 1):
        # Each layer's n_inputs is the n_neurons of the layer before it.
        network.append(Layer_Dense(sizes[i], sizes[i + 1]))
        last = i == len(sizes) - 2
        network.append(Activation_Softmax() if last else Activation_ReLU())
    return network


def forward_network(network, X):
    """Run X through the objects in order and return the probabilities."""
    values = X
    for component in network:
        component.forward(values)
        values = component.output          # the next object reads this output
    return values
